    /// Replace file
    ///
    /// Replace an existing file with new content while preserving the file ID. The operation follows these steps:
    /// 1\. The isUploaded flag is set to false to mark the file as being updated
    /// 2\. The file content is replaced in the storage backend
    /// 3\. File metadata is updated (size, mime\-type, isUploaded, etc.)
    ///
    /// Each step is atomic, but if a step fails, previous steps will not be automatically rolled back.
    ///
    /// Performs PUT /files/{id}.
    pub async fn replace_file(
        &self,
        id: &str,
        body: ReplaceFileBody,
    ) -> Result<Response<FileMetadata>, Error> {
        let url = http::append_path(self.base_url.as_str(), &["files", id])?;
        let mut request = self.http.request(reqwest::Method::PUT, url);
        let mut form = reqwest::multipart::Form::new();
        if let Some(v) = &body.metadata {
            form = form.part(
                "metadata",
                reqwest::multipart::Part::text(serde_json::to_string(v)?)
                    .mime_str("application/json")?,
            );
        }
        if let Some(v) = body.file {
            let part = reqwest::multipart::Part::bytes(v.content).file_name(v.file_name);
            let part = if let Some(content_type) = v.content_type {
                part.mime_str(&content_type).map_err(|_| {
                    Error::Config(format!("invalid multipart content type {content_type:?}"))
                })?
            } else {
                part
            };
            form = form.part("file", part);
        }
        request = request.multipart(form);
        let (status, headers, bytes) = http::send(request, self.session_sink.as_ref()).await?;
        let body = serde_json::from_slice(&bytes)?;
        Ok(Response {
            body,
            status,
            headers,
        })
    }

